		parts := strings.Fields(inputLines[lineIdx])
		lineIdx++
		if len(parts) < 2 {
			continue
		}
		a, _ := strconv.Atoi(parts[0])
		b, _ := strconv.Atoi(parts[1])
		adj[a] = append(adj[a], b)
		adj[b] = append(adj[b], a)
	}

	f := false
	noOfVertices := 20

	for j := 1; j <= 7; j++ {
		a7 := adj[j]
		for i := 1; i <= 7; i++ {
			if i == j {
				continue
			}
			other := adj[i]
