			if len(x) == 0 {
				f = true
				break
			} else if len(x) < noOfVertices {
				noOfVertices = len(x)
			}
		}
		if f {
			break
		}
	}

	if f {
		fmt.Println(e)
	} else {
		fmt.Println(e - noOfVertices)
	}
}

func intersection(a, b []int) []int {
	bMap := make(map[int]bool)
	for _, val := range b {
		bMap[val] = true
	}
	var result []int
	for _, val := range a {
		if bMap[val] {
			result = append(result, val)
		}
	}
	return result
}

